package polski.grammar

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import polski.data.*
import polski.data.rows.oracle.*
import polski.model.*

/**
 * Loops [grammarCaseRows] (generated by `biome generate` from dsl/grammar-oracle/grammar.core-data,
 * itself converted once from the pinned, independent fixture tests/fixtures/kotlin-parity/grammar.json
 * by dsl/derive-grammar-oracle.mjs — see Plans/Architecture/DSL-MIGRATION-PLAN.md block F). Was 1979
 * hand-expanded `assertEquals` calls, one pinned expectation per case; the data moved to
 * dsl/grammar-oracle/ so the oracle lives in one place and one format instead of two (grammar.json
 * and this file both encoding it).
 *
 * Two verb cases (`buyDone`/`doDone`, present tense of a perfective verb) expect [verbForm] to throw
 * rather than return a form; `row.expectError` marks those, and `row.expected` then holds the thrown
 * message instead of the usual pipe-joined fields.
 */
class GrammarParityTest {
    @Test
    fun allCases() {
        for (row in GRAMMAR_CASE_ROW_ROWS) {
            val actual: String? = when (row.kind) {
                GrammarCaseRowKind.NOUN -> nounById(row.nounId!!).let { n ->
                    listOf(n.lemma, n.meaning, n.gender.id, nounForm(n.id, GramCase.fromId(row.gramCase!!), NumberGram.fromId(row.number!!))).joinToString("|")
                }
                GrammarCaseRowKind.ADJECTIVE -> adjectiveById(row.adjectiveId!!).let { a ->
                    listOf(a.lemma, a.meaning, adjectiveForm(a.id, Gender.fromId(row.gender!!), GramCase.fromId(row.gramCase!!), NumberGram.fromId(row.number!!))).joinToString("|")
                }
                GrammarCaseRowKind.VERB -> if (row.expectError == true) {
                    assertFailsWith<IllegalStateException> {
                        verbForm(row.verbId!!, Tense.fromId(row.tense!!), Person.fromId(row.person!!), NumberGram.fromId(row.number!!), Gender.fromId(row.gender ?: "m-personal"))
                    }.message
                } else {
                    verbById(row.verbId!!).let { v ->
                        listOf(
                            v.lemma, v.meaning, v.aspect.id, v.futureType.id, v.perfectivePair.orEmpty(),
                            verbForm(row.verbId!!, Tense.fromId(row.tense!!), Person.fromId(row.person!!), NumberGram.fromId(row.number!!), Gender.fromId(row.gender ?: "m-personal")),
                        ).joinToString("|")
                    }
                }
                GrammarCaseRowKind.PRONOUN -> GramCase.entries.joinToString("|") { personalPronouns.getValue(row.pronounId!!).getValue(it) }
                GrammarCaseRowKind.POSSESSIVE -> possessives.first { it.id == PossessiveId.fromId(row.owner!!) }.label + "|" +
                    possessiveForm(PossessiveId.fromId(row.owner!!), Gender.fromId(row.gender!!), NumberGram.fromId(row.number!!), GramCase.fromId(row.gramCase!!))
                GrammarCaseRowKind.PHRASE -> nounPhrase(row.nounId!!, GramCase.fromId(row.gramCase!!), NumberGram.fromId(row.number!!), row.adjectiveId!!, PossessiveId.fromId(row.owner!!))
                GrammarCaseRowKind.SENTENCE -> caseSentence(SentenceSeed(row.nounId!!, row.adjectiveId!!), GramCase.fromId(row.gramCase!!), PossessiveId.fromId(row.owner!!), NumberGram.fromId(row.number!!))
                GrammarCaseRowKind.SKILL -> skillById(row.skillId!!).let { s ->
                    listOf(s.id, s.title, s.group, s.level, s.formula, s.theory, s.hint, s.prerequisites.joinToString(",")).joinToString("|")
                }
            }
            assertEquals(row.expected, actual, row.id)
        }
    }
}
